{
  "id": "ask-user-question-already-decided",
  "severity": "advisory",
  "scope": "action",
  "failureMessage": "a blocking question spends real human wall-clock, and most are already answered by an instruction in context, by state one read away, or by the recommended option being the status quo",
  "guardToolCalls": [
    {
      "tool": "AskUserQuestion",
      "inputField": "questions",
      "match": "/./",
      "what": "a blocking question to the owner",
      "fix": "ask only a fork you cannot resolve yourself and batch every open decision into this one call; for anything answerable from the instruction or the tree, act and say what you assumed"
    }
  ]
}

