file.content:
// The machine-readable records a task's execution leaves in an Actions log
// (skill-usage-metrics DESIGN §4.2), and the parsers that read them back.
//
// TWO FAMILIES, ONE OF THEM HISTORICAL. `claudinite-task-run` was the SLOT
// scheduler's own line, one per due task per run; the slot scheduler is retired
// (#974) and nothing writes that line any more. The parser stays, and only the
// parser: Actions logs from before the retirement are still inside their retention
// window, and the usage fold still counts them. Nothing new should be taught this
// shape — `claudinite-task-exec` below is the live record.
//
// The counts these produce are exact within the Actions log retention window, and
// that is worth stating next to the capture-derived counts they land beside.

// The five things a slot scheduler run could do with a due task. One name per
// outcome, used verbatim as the counter key in the aggregate, so there is no
// mapping table between "what the run said" and "what the fold counted" to drift.
export const TASK_RUN_OUTCOMES = Object.freeze([
  // A dispatch issue was filed: an agent session ran this task.
  'agent',
  // The task ran with NO agent — an `agent_model: none` task (code-work is the
  // whole task), or an agentful one whose code-work requested no agent phase.
  // Kebab, not the declaration field's `code_work`: this word is a WIRE token,
  // constrained to the line format's `[a-z-]+` charset.
  'code-work',
  // Due, but its precondition said there was nothing to do.
  'skipped',
  // Its code-work failed; the run converged the task to a needs-human issue.
  'failed',
  // Due and past its precondition, but no NEW agent run started: this slot was
  // already dispatched (exactly-once), an earlier dispatch is still open
  // (at-most-one-open), or another task claimed the run exclusively. Work that
  // was wanted and did not happen this run.
  'deferred',
]);

// An empty per-task counter row — every outcome present, zeros included, so a row's
// shape never depends on which outcomes a task happened to hit.
export const emptyTaskRun = () => Object.fromEntries(TASK_RUN_OUTCOMES.map((o) => [o, 0]));

// The line format. `v1` is the shape's version: a reader that meets a `v2` line
// knows it is looking at something it was not written for, instead of silently
// half-parsing it.
export const TASK_RUN_TAG = 'claudinite-task-run';
const VERSION = 'v1';

// Actions stamps every log line with its own timestamp before the command's output,
// so the parse tolerates that prefix — without it, a fetched log reads as having
// printed nothing at all.
const LINE_RE = new RegExp(
  String.raw`^(?:\S+\s+)?${TASK_RUN_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
);

// One line → `{ pack, task, slotId, outcome }`, or null for anything that is not a
// record of this version. Deliberately strict: an unknown outcome word is NOT a
// record, because counting it would mint a counter key nothing ever reads.
// The code phase has been renamed twice, and job logs outlive both renames:
// `preprocess` (pre-2026-08-06) and `prework` (pre-2026-08-18) are the earlier
// words for what is now `code-work`. Runs logged under either still parse, each
// normalized straight to the canonical word.
// Exported because the outcome words are also the usage aggregate's counter KEYS,
// and that file holds rows written under the older words. Its decode renames them
// by this same map, so a rename never silently drops a historical count.
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_TASK_RUN_OUTCOMES = Object.freeze({ preprocess: 'code-work', prework: 'code-work' });

export function parseTaskRun(line) {
  const m = LINE_RE.exec(line);
  if (!m) return null;
  const [, pack, task, slotId, word] = m;
  const outcome = LEGACY_TASK_RUN_OUTCOMES[word] ?? word;
  if (!TASK_RUN_OUTCOMES.includes(outcome)) return null;
  return { pack, task, slotId, outcome };
}

// Every record in one job log. The log is the whole job's output — this picks its
// own lines out of it and ignores everything else.
export function parseTaskRuns(text) {
  const out = [];
  for (const line of String(text ?? '').split('\n')) {
    const rec = parseTaskRun(line);
    if (rec) out.push(rec);
  }
  return out;
}

// --- executor-side execution records ------------------------------------------
// The historical records above say what the retired slot scheduler DID with a due
// task; these record what an EXECUTOR SESSION did with the work it ran. Printed by executor-side code
// (resolve-dispatch on a terminal verdict, record-exec.mjs at convergence), they
// land in the session transcript, ride to the conversation-logs branch with the
// executor's capture step, and the usage fold counts them deterministically —
// the "task statuses out of the conversation logs" half of the census (owner,
// 2026-08-06). Same single-home rule: renderer and parser sit here together.

export const TASK_EXEC_STATUSES = Object.freeze([
  // The dispatch ran to completion within its ceiling; the issue was closed.
  'success',
  // The run failed (task failure or ceiling violation); the item parked.
  'failed',
  // The dispatch named a task file the repo no longer carries — retired, its pack
  // undeclared, or the item's stored path left behind by a pack rename — and the
  // executor closed the issue as obsolete. Not a failure.
  'task-gone',
  // The dispatch was malformed (bad path shape, unparseable declaration) and was
  // parked without running.
  'invalid',
]);

export const TASK_EXEC_TAG = 'claudinite-task-exec';

// The bracketed field is the OCCURRENCE'S IDENTITY, which is a different thing under
// each dispatch mechanism: a slot id (`d2026-08-06`) where slots decide what runs, and
// the work item's issue number (`#867`) where the queue does. `slotId` keeps its name
// for the fielded records that already carry one; what it must never become is a
// constant, since it is the only join from a record back to the work it describes.
export const renderTaskExec = ({ pack, task, slotId, status }) =>
  `${TASK_EXEC_TAG} ${VERSION} ${pack}/${task} [${slotId ?? 'unknown'}] ${status}`;

const EXEC_LINE_RE = new RegExp(
  String.raw`(?:^|\s)${TASK_EXEC_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
);

export function parseTaskExec(line) {
  const m = EXEC_LINE_RE.exec(line);
  if (!m) return null;
  const [, pack, task, slotId, status] = m;
  if (!TASK_EXEC_STATUSES.includes(status)) return null;
  return { pack, task, slotId, status };
}

export function parseTaskExecs(text) {
  const out = [];
  for (const line of String(text ?? '').split('\n')) {
    const rec = parseTaskExec(line);
    if (rec) out.push(rec);
  }
  return out;
}

content.content:
1	// THE TERMINAL TRANSITION, IN CODE (#892; docs/PRINCIPLES.md).
2	// A work-item session ends by performing five ordered side effects — comment,
3	// drop `task:agent`, add the outcome label, carry the execution record, close
4	// with the right state reason — on the item it holds, and nothing else: a
5	// converge never writes to another work item (docs/PRINCIPLES.md; #1373 reversed
6	// an earlier attempt). Releasing a dependent a close may have freed is the scheduler run's
7	// job alone. Asking a session to perform these effects from prose is asking for
8	// it at the moment its context is fullest and the remaining work looks like
9	// formality; both of the first two live agentic runs got part of it wrong,
10	// silently, in different ways.
11	//
12	// THIS FILE RUNS IN ONE PLACE: INSIDE A WORK-ITEM SESSION. `queue/instructions.md`
13	// step 6 is its only caller — no workflow invokes it, no module imports it. The
14	// Actions side converges through `executor.mjs`, which owns that path entirely.
15	//
16	// SO EVERY LINE HERE ASSUMES MCP, AND NOTHING HERE MAY REACH THE NETWORK. A session
17	// holds its GitHub access through its own tools; a subprocess it spawns has no route
18	// to them and none to the REST API. This file therefore PLANS a transition and
19	// PRINTS it addressed to those tools — it never performs one. Printing the calls is
20	// the successful outcome, on stdout, exit 0. That is not a fallback: it is the only
21	// path, and it must never read as a failure. A REST executor lived here once and did
22	// (#1491) — a session met its `console.error` before it met the path written for it,
23	// reported that it could not converge, and left the item to the janitor's 3h leash,
24	// which parks a finished run as a human decision. Five sampled items across five
25	// repos were exactly that.
26	//
27	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
28	// JUDGMENT — which outcome, and the prose of what happened — and the CODE decides
29	// every step of the transition. A session that stops early now leaves an item that
30	// is visibly unconverged, rather than one that looks finished and is not.
31	//
32	// Usage — the item is handed in, because this process cannot read it:
33	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
34	//                          --summary <text> [--pr <n>]
35	//                          --repo <owner/name> --item-file <path to the issue as JSON>
36	
37	import { readFile } from 'node:fs/promises';
38	import { pathToFileURL } from 'node:url';
39	import { renderTaskExec } from '../run-record.mjs';
40	import {
41	  AGENT, TASK_DONE, STATUS_RUNNING_AGENT, isStatus, machineBlockOf,
42	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
43	  QUEUED_LABEL, IN_REVIEW_LABEL, ORIGIN_LABELS, hasLabel,
44	  parseWorkItemTitle, parseWorkItemBody, spellingsOf, labelNames,
45	  editItemBody, withEndsWhen,
46	} from './work-item.mjs';
47	
48	// What a session may claim, and what each one means for the item. `record` is the
49	// execution-record status, and `null` means no record: an approval park is a run
50	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
51	// a fifth status would be stored data every decoder in the fleet must learn.
52	export const OUTCOMES = Object.freeze({
53	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
54	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
55	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
56	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
57	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
58	});
59	
60	export function parseArgs(argv) {
61	  const args = {};
62	  for (let n = 0; n < argv.length; n += 1) {
63	    const m = /^--([a-z-]+)$/.exec(argv[n]);
64	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
65	  }
66	  const issue = Number(args.issue);
67	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
68	  if (!OUTCOMES[args.outcome]) {
69	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
70	  }
71	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
72	  if (args.outcome === 'approval' && !args.pr) {
73	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
74	  }
75	  return {
76	    issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null,
77	    repo: args.repo || null, itemFile: args['item-file'] || null,
78	  };
79	}
80	
81	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
82	// terminal state onto the wrong issue: this runs from a session, whose whole
83	// notion of which item it holds came from an untrusted fire payload.
84	export function refusal(item, issue) {
85	  if (!item) return `#${issue} could not be read`;
86	  // A marked issue IS its own item (PRINCIPLES.md), so the title test cannot be the
87	  // membership test any more: what says this is one is the machine block adoption
88	  // wrote — never the body's first line, which on a marked issue is a person's prose.
89	  //
90	  // THREE SIGNALS, ANY ONE SUFFICIENT. A membership test gated on the single artifact
91	  // it exists to validate refuses exactly the items that artifact is missing from: an
92	  // issue adopted before the block delimiters existed carries its fields bare, and was
93	  // refused here into a by-hand convergence that dropped half the transition
94	  // (missingbulb/Shepherd#360). The origin label is the independent one — carried for
95	  // life, and platform-write-gated like the block was.
96	  const marked = ORIGIN_LABELS.some((name) => hasLabel(item, name));
97	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null && !marked) {
98	    return `#${issue} is not a Claudinite work item`;
99	  }
100	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
101	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
102	    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
103	  }
104	  return null;
105	}
106	
107	// The record line for this item, or null where the vocabulary has no true answer.
108	export const recordLine = (item, status) => {
109	  const parsed = parseWorkItemTitle(item.title);
110	  return status && parsed
111	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
112	    : null;
113	};
114	
115	// The comment one converge writes: the session's account, then the record, so a
116	// reader and a parser both find what they came for in one place.
117	export function convergeComment(item, { summary, pr, record }) {
118	  const rec = recordLine(item, record);
119	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
120	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
121	  return `${summary.trim()}${waiting}${line}`;
122	}
123	
124	// THE TRANSITION AS DATA (#1374). The side effects were a straight line of
125	// `await api.…` calls, which silently made REST the only way to perform them —
126	// and the sessions `invoke.mjs` hands work to have no REST route to their own
127	// repository, so the last step of every agentic run was the one step that
128	// environment could not take.
129	//
130	// So the sequence is planned as OPS and executed by whoever can. The planner is
131	// the single source of what a convergence IS; the executors differ only in
132	// transport. The session still supplies nothing but the judgment.
133	//
134	// Removes are granular and unconditional — every spelling of the status being
135	// left, not only the ones this snapshot shows (apply-status.mjs's rule: a member's
136	// items outlive its converges, so an item may wear an older engine's spelling).
137	export function convergeOps(item, plan) {
138	  const spec = OUTCOMES[plan.outcome];
139	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record }) }];
140	
141	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
142	  // the durable one (Actions logs expire, the item does not), while this printed
143	  // copy lands in the session transcript, which is what the usage fold reads for
144	  // the task-status census.
145	  const rec = recordLine(item, spec.record);
146	  if (rec) ops.push({ kind: 'record', line: rec });
147	
148	  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
149	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
150	  }
151	  // ONE label, on both paths: the outcome IS the status. A park in particular is
152	  // never a pair, so nothing can be half-applied (#1385).
153	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
154	
155	  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
156	  // merge or close the pull request; this says the same thing where the janitor can
157	  // read it, so the item ends when that happens instead of waiting for someone to
158	  // notice it already did. Every park that names one gets it, not only `approval`.
159	  if (!spec.closes && plan.pr) {
160	    ops.push({ kind: 'setBody', issue: item.number, body: editItemBody(item.body, (m) => withEndsWhen(m, plan.pr)) });
161	  }
162	
163	  // SUPERSEDING (PRINCIPLES.md). The executor decided at resolution which of this
164	  // task's earlier pull requests a `supersede_existing_pr` run replaces and stamped
165	  // them on the item; they close only once THIS run's own pull request exists — a
166	  // run that delivered nothing, or broke, leaves them where they were, so a review
167	  // member's pending pull request is never taken away for nothing.
168	  const { supersedes } = parseWorkItemBody(item.body ?? '');
169	  if (plan.pr && (plan.outcome === 'done' || plan.outcome === 'approval')) {
170	    for (const number of supersedes) {
171	      ops.push({ kind: 'closePull', number, successor: plan.pr, body: `Superseded by #${plan.pr}, a later run of the same task. Closing this one.` });
172	    }
173	  }
174	
175	  if (spec.closes) {
176	    // A DONE TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed (#1489,
177	    // reversing docs/PRINCIPLES.md's "never a marked issue"). `done` is the one outcome
178	    // that means nothing is left for anyone to act on, so an issue left open under
179	    // it asks its author to come and agree with what the run already settled. Every
180	    // other outcome parks, and a park leaves the issue open to be waited on.
181	    ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
182	    return ops;
183	  }
184	
185	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
186	  // (PRINCIPLES.md). Only the approval park: a failure deliberately writes nothing and
187	  // leaves `claude-queued` standing, because re-arming work that writes code is a
188	  // person's decision and that standing label is what stops the next scheduler run
189	  // queueing a second run of the same request. Only a LEGACY shadow item writes
190	  // back to a different issue.
191	  const { request } = parseWorkItemBody(item.body ?? '');
192	  if (request && request !== item.number && plan.outcome === 'approval') {
193	    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
194	    ops.push({ kind: 'removeLabel', issue: request, name: QUEUED_LABEL });
195	    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
196	  }
197	  return ops;
198	}
199	
200	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
201	// does have. Two differences forced by that surface, both handled here rather than
202	// left to the session to work out:
203	//
204	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
205	//    granular removes and adds are folded into the FINAL set here, computed from the
206	//    labels this item was read with. Everything not a status label is carried through.
207	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
208	//    usage fold reads the census out of the session transcript.
209	export function sessionScript(item, plan, repo) {
210	  const [owner, name] = String(repo).split('/');
211	  const lines = [];
212	  let n = 0;
213	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
214	
215	  // The item's own label set can be computed exactly, because the item was read
216	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
217	  // read-modify-write naming only the change, and never as a computed set, which
218	  // would silently drop every label this process never saw.
219	  const own = new Set(labelNames(item));
220	  const foreign = [];
221	  // The body write folds into the item's own `issue_write`, which is one call
222	  // either way. A park never closes, so the step it folds into is the trailing
223	  // label write below.
224	  let newBody = null;
225	
226	  for (const op of convergeOps(item, plan)) {
227	    if (op.kind === 'comment') {
228	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
229	    } else if (op.kind === 'record') {
230	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
231	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
232	      if (op.issue === item.number) {
233	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
234	      } else {
235	        foreign.push(op);
236	      }
237	    } else if (op.kind === 'setBody' && op.issue === item.number) {
238	      newBody = op.body;
239	    } else if (op.kind === 'close') {
240	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
241	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
242	      own.clear();
243	    } else if (op.kind === 'closePull') {
244	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.number}\` (a pull request), body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
245	      step(`\`update_pull_request\` — owner \`${owner}\`, repo \`${name}\`, pullNumber \`${op.number}\`, state \`closed\``);
246	    }
247	  }
248	  // A park never closed, so its label write is still owed.
249	  if (own.size) {
250	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
251	      + ` labels \`${JSON.stringify([...own])}\``
252	      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
253	  }
254	  for (const op of foreign) {
255	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
256	      + ` Read that issue's current labels first and write them back with only this one change —`
257	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
258	  }
259	  return lines.join('\n');
260	}
261	
262	async function main() {
263	  const plan = parseArgs(process.argv.slice(2));
264	  if (plan.error) {
265	    console.error(`converge-item: ${plan.error}`);
266	    process.exit(2);
267	  }
268	
269	  // The repo this item lives in. `--repo` is what instructions.md passes; the two
270	  // environment names answer for a session whose harness sets one of them.
271	  const repo = plan.repo ?? process.env.CLAUDINITE_ITEM_REPO ?? process.env.GITHUB_REPOSITORY ?? null;
272	  if (!repo) {
273	    console.error('converge-item: --repo <owner/name> names the repository this item lives in');
274	    process.exit(2);
275	  }
276	
277	  // THE ITEM IS HANDED IN. This process cannot read it — that is the whole premise
278	  // of the file — so the session reads it with its own tools and passes it through.
279	  // A file rather than an argument: an item's body is prose of arbitrary length, and
280	  // a shell-quoted one is a quoting bug waiting for the first apostrophe.
281	  // `CLAUDINITE_ITEM_JSON` stays readable for a member whose instructions.md is a
282	  // cycle behind, since a mount updates on its own schedule.
283	  const raw = plan.itemFile
284	    ? await readFile(plan.itemFile, 'utf8')
285	    : (process.env.CLAUDINITE_ITEM_JSON ?? '');
286	  let item = null;
287	  try { item = JSON.parse(raw || 'null'); } catch { item = null; }
288	  if (!item) {
289	    console.error('converge-item: --item-file must hold the issue as your GitHub tools returned it'
290	      + ' (number, title, body, state, labels).\n'
291	      + `Read it first: \`issue_read\` method \`get\` on ${repo} #${plan.issue}, save the JSON, pass the path.`);
292	    process.exit(2);
293	  }
294	
295	  const no = refusal(item, plan.issue);
296	  if (no) { console.error(`converge-item: ${no}`); process.exit(1); }
297	
298	  // The successful outcome. Everything below is the transition, decided here and
299	  // performed by the session — so it goes to stdout and the process exits clean.
300	  console.log('converge-item: the transition below is yours to execute.\n'
301	    + 'Make these calls with your GitHub tools, in this order, changing nothing. Then stop.\n');
302	  console.log(sessionScript(item, plan, repo));
303	}
304	
305	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
306	  main().catch((e) => { console.error(e); process.exit(1); });
307	}
